package com.logsense.security;
import com.logsense.config.LogSenseProperties;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.HttpHeaders;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.List;
@Component public class ApiKeyFilter extends OncePerRequestFilter {private final LogSenseProperties p;public ApiKeyFilter(LogSenseProperties p){this.p=p;}@Override protected boolean shouldNotFilter(HttpServletRequest r){String uri=r.getRequestURI();return uri.startsWith("/actuator/health")||uri.equals("/error")||uri.equals("/")||uri.equals("/index.html")||uri.startsWith("/api/v1/chat");}@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String expected=p.security()==null?null:p.security().apiKey();String supplied=r.getHeader("X-API-Key");if(supplied==null){String h=r.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer "))supplied=h.substring(7);}boolean valid=expected!=null&&!expected.isBlank()&&supplied!=null&&MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8));if(valid)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("api-key-client","N/A",List.of(new SimpleGrantedAuthority("ROLE_LOG_READER"),new SimpleGrantedAuthority("ROLE_ADMIN"))));else if(expected!=null&&!expected.isBlank()&&r.getHeader(HttpHeaders.AUTHORIZATION)==null){s.sendError(401,"Missing or invalid API key");return;}c.doFilter(r,s);}}
